package com.fitbite;
import static org.junit.jupiter.api.Assertions.*; import com.fitbite.entity.*; import com.fitbite.repository.*; import com.fitbite.recommendation.*; import com.fitbite.service.*; import org.junit.jupiter.api.*; import org.mockito.*; import java.util.*;
class RecommendationServiceTest { @Test void ingredientMatchCalculatesPercentage(){var repo=Mockito.mock(RecipeRepository.class);var saved=Mockito.mock(RecommendationRepository.class);var current=Mockito.mock(CurrentUserService.class);var rs=Mockito.mock(RecipeService.class);var service=new RecommendationService(repo,saved,current,rs);var rice=Ingredient.builder().name("rice").build();var egg=Ingredient.builder().name("egg").build();var r=Recipe.builder().id(1L).name("Egg Rice").ingredients(new ArrayList<>()).build();r.addIngredient(rice,"1 cup");r.addIngredient(egg,"2");Mockito.when(repo.findAll()).thenReturn(List.of(r));var out=service.byIngredients(List.of("rice"));assertEquals(50.0,out.get(0).matchPercentage());assertEquals("Egg Rice",out.get(0).recipeName());}}
